// Host tool: lifts the kernel test programs (kernel_program_code.hpp) with the
// P2.3 lifter into C++ that uses the real runtime header (guest.hpp).
// Usage: lgp_lift_kernel_programs <out.cpp>
#include <cstdio>
#include <fstream>
#include <string>

#include "kernel_program_code.hpp"
#include "lgp/recomp/lifter.hpp"

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s <out.cpp>\n", argv[0]);
        return 2;
    }
    using namespace lgp_test;
    std::string out =
        "// Generated by lgp_lift_kernel_programs from tests/runtime/kernel_program_code.hpp. Do not edit.\n"
        "#include \"lgp/lifted/lifted.hpp\"\n\n";
    std::string table = "extern const lgp::LiftedFn kLiftedPrograms[] = {\n";
    size_t index = 0;
    for (const ProgramCode& p : program_codes()) {
        const std::vector<uint32_t>& words = p.words;
        const uint64_t end = kProgramBase + 4 * words.size();
        lgp::recomp::LiftOptions options;
        options.name_prefix = "lgp_prog" + std::to_string(index) + "_";
        options.precise_fault_pc = true;  // the tests compare the pc of a faulting access
        lgp::recomp::Lifter lifter(
            [&](uint64_t va, uint32_t& insn) {
                if (va < kProgramBase || va >= end || (va & 3) != 0)
                    return false;
                insn = words[(va - kProgramBase) / 4];
                return true;
            },
            {kProgramBase}, options);
        lgp::recomp::LiftFunction fn;
        fn.entry = kProgramBase;
        fn.blocks.push_back({kProgramBase, end});
        lgp::recomp::LiftStats stats;
        out += lifter.declarations();
        out += lifter.lift(fn, stats);
        out += "\n";
        if (stats.unsupported != 0) {
            std::fprintf(stderr, "%s: %llu unsupported instructions\n", p.name,
                         static_cast<unsigned long long>(stats.unsupported));
            return 1;
        }
        table += "    &" + lifter.function_name(kProgramBase) + ",\n";
        ++index;
    }
    table += "};\n";
    std::ofstream f(argv[1]);
    f << out << table;
    return f.good() ? 0 : 1;
}
